# Generated by test-lab — blind adversarial evaluation
"""Regression tests for bounded retrieval-query selection."""

from live_evidence.query_bounds import bounded_query
from live_evidence.readiness import ReadinessVerdict


def test_leetcode_tail_confirmation_keeps_parentheses_problem_context() -> None:
    raw = (
        "Correct. So to make it clear, let me paste in the sample in terms of "
        "looking for minimum number of parentheses. As you can see, we remove "
        "the last closing parenthesis because there is no corresponding opening. "
        "A opening parentheses always has to come before closing, right?"
    )
    verdict = ReadinessVerdict(
        question_asked_yet=True,
        question_complete=True,
        ready_to_answer=True,
        blocking_reason="none",
        question_type="leetcode",
        actionable=True,
        canonical_question="A opening parentheses always has to come before closing, right?",
        confidence=0.8,
    )

    query = bounded_query(raw, verdict)

    assert "remove the minimum number of parentheses" in query
    assert "valid" in query
    assert len(query) <= 220


def test_parentheses_problem_context_survives_missing_verdict() -> None:
    raw = (
        "We need the minimum number of parentheses removed so the string is "
        "valid. The dangling closing paren has no corresponding opening. "
        "Opening parentheses always have to come before closing, right?"
    )

    query = bounded_query(raw, None)

    assert "remove the minimum number of parentheses" in query
    assert "valid" in query
    assert len(query) <= 220
